{
  "technical_and_design_decisions": [
    "Implement the Capabilities Framework by extending the channel config with three capability maps (channel, application, orderer) and enforce crash-on-incompatibility for v1.1.",
    "Refactor the chaincode shim to support Read-Your-Writes (RYW) by checking the transient store during GetState calls.",
    "Use dependency injection to remove chaincode singletons, replacing them with injectable components for testability.",
    "Define the MSPConfig as an interface to decouple config construction from configtxgen.",
    "Generate peer and orderer configuration files dynamically from a World config during setup.",
    "Implement a validation interface for the new lifecycle that includes a default policy for '+lifecycle' chaincode.",
    "Assume crash-on-incompatibility is acceptable for v1.1 to ensure data integrity.",
    "Use existing CouchDB benchmarks and adapt them for performance testing."
  ],
  "assumptions": [
    "The World config for U7 is already available and structured for config generation.",
    "The video for U3 requires minimal editing and can be produced with basic tools.",
    "The RYW feature in U2 does not require changes to existing chaincode APIs beyond the shim.",
    "The lifecycle validation interface in U8 can be implemented without affecting existing chaincode lifecycle logic.",
    "The MSPConfig interface in U5 will not break backward compatibility with existing configtxgen workflows.",
    "The chaincode singleton removal in U6 will not introduce new dependencies or require major architectural changes.",
    "The CouchDB performance tests in U4 will use standard query patterns and not require custom benchmarking tools.",
    "The Capabilities Framework in U1 will not require additional capabilities beyond the V1.1 flag for v1.1."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design Capabilities Framework Config Structure",
      "activity_description": "Define the channel, application, and orderer capability maps in the channel config and update the config proto definitions.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Orderer Capability Checks",
      "activity_description": "Add logic to the orderer to validate and enforce orderer and channel capabilities, crashing if unsupported.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Peer Capability Checks",
      "activity_description": "Add logic to the peer to validate and enforce application and channel capabilities, crashing if unsupported.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Update Upgrade Process Documentation",
      "activity_description": "Document the reconfiguration transaction process for enabling V1.1 capabilities across channels and orderers.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Modify Chaincode Shim for RYW",
      "activity_description": "Update the chaincode shim to allow GetState to read keys written in the current transaction via the transient store.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "Add RYW Tests and Documentation",
      "activity_description": "Write unit tests for the RYW feature and update chaincode developer documentation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Create Adding Organizations Video",
      "activity_description": "Produce a video tutorial demonstrating the process of adding organizations to a running network.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Write Adding Organizations Documentation",
      "activity_description": "Create step-by-step documentation with diagrams for adding organizations without network downtime.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Set Up CouchDB Performance Benchmarks",
      "activity_description": "Configure test cases to measure query performance using CouchDB as the state database.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "Run CouchDB Performance Tests",
      "activity_description": "Execute performance tests and collect metrics for various query patterns.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Document CouchDB Performance Results",
      "activity_description": "Compile and present performance data in a report for network administrators.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "Refactor MSPConfig to Interface",
      "activity_description": "Convert MSPConfig into an interface to allow custom config construction outside configtxgen.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A13",
      "activity_name": "Update configtxgen for MSPConfig Interface",
      "activity_description": "Modify configtxgen to use the new MSPConfig interface without breaking existing workflows.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A14",
      "activity_name": "Test MSPConfig Interface Changes",
      "activity_description": "Validate that the refactored MSPConfig works with both new and existing configtxgen use cases.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "Remove Chaincode Singletons",
      "activity_description": "Identify and replace all chaincode singletons with injectable components for improved testability.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A16",
      "activity_name": "Test Singleton Removal",
      "activity_description": "Ensure that removing singletons does not break existing chaincode functionality or tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A17",
      "activity_name": "Implement Config Generation from World Config",
      "activity_description": "Add logic to generate peer/core.yaml and orderer.yaml based on values in the World config.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A18",
      "activity_name": "Integrate Config Generation with Setup",
      "activity_description": "Ensure the generated config files are used during peer and orderer initialization.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A19",
      "activity_name": "Test Config Generation Workflow",
      "activity_description": "Verify that config files are correctly generated and applied in test environments.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A20",
      "activity_name": "Design Lifecycle Validation Interface",
      "activity_description": "Define the interface for returning validation parameters for chaincode, including the '+lifecycle' edge case.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A21",
      "activity_name": "Implement Lifecycle Validation Logic",
      "activity_description": "Code the validation interface to return correct parameters for chaincode and '+lifecycle'.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A22",
      "activity_name": "Handle '+lifecycle' Default Policy",
      "activity_description": "Automatically generate a majority-org endorsement policy for the '+lifecycle' chaincode.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 62
  }
}

